        "::give bronze_axe 1",
        "::give knife 1",
        "::setlevel crafting 31",
        "::setlevel woodcutting 36",
        "::setlevel attack 99",
        "::setlevel strength 99",
        "::setlevel defence 99",
        "::setlevel hitpoints 99",
        "::give shark 20",
        "::setlevel magic 31",
        "::give lawrune 1",
