        "::give earthrune 1",
    },

    run = function(t)
        local bind_result, bind_detail = t.quest.bind({
            varp = "varp147_zanaris",
            constants = {
                complete = 6,
                not_started = 0,
                spirit_defeated = 3,
                spoken_shamus = 2,
                staff_made = 5,
