                tree_chopped = 4,
            },
            row = "quest_lostcity",
            display = "Lost City",
            points = 3,
        })
        t.step("quest.bind", bind_result == "ok" and "PASS" or "FAIL", bind_detail)

        t.ticks(3)
        t.expect("quest.stage.not_started", t.quest.expect_stage("not_started"))

        t.exec("goto-talkToWarrior", t.player.goto_tile, 3149, 3207, 0)
        t.exec("talkToWarrior", t.player.talk_to, "warrioradventurerpg", 1)
        t.exec("talkToWarrior-dialog", t.chat.play, {
            "npc:Hello there traveller.",
            "choose:What are you camped here for?",
            "player:What are you camped here for?",
            "npc:We're looking for Zanaris",
            "choose:What makes you think it's out here?",
            "player:What makes you think it's out here?",
            "npc:Don't you know of the legends",
            "choose:If it's hidden how are you planning to find it?",
            "player:If it's hidden how are you planning to find it?",
            "npc:Well, we don't want to tell anyone",
            "choose:Looks like you don't know either.",
            "player:Well, it looks to me like YOU",
            "npc:Of course we know!",
            "player:Leprechaun?",
            "npc:GAH! I didn't mean",
            "player:So a leprechaun knows",
            "npc:Ye.. uh, no.",
            "player:Thanks for the help!",
            "npc:Help? What help?",
        })
        t.ticks(2)
        t.expect("quest.stage.started", t.quest.expect_stage("started"))

        t.exec("goto-chopTree", t.player.goto_tile, 3140, 3213, 0)
        local chop_result, chop_detail = t.player.click_loc("leprechauntree", 1)
        t.check("chopTree-swing", chop_result == "ok" or chop_result == "timeout", "click_loc leprechauntree -> " .. tostring(chop_result) .. " " .. tostring(chop_detail))
        t.exec("chopTree", t.npc.await_present, "zanarisleprechaun", 15, 10)
        t.exec("talkToShamus", t.player.talk_to, "zanarisleprechaun", 1)
        t.exec("talkToShamus-dialog", t.chat.play, {
            "npc:Ay yer big elephant!",
            "player:I want to find Zanaris.",
            "npc:Zanaris is it now?",
            "player:...but... I thought",
            "npc:Aye that it is!",
            "choose:I've been in that shed, I didn't see a city.",
            "player:I've been in that shed.",
            "npc:Oh, was I fergetting to say?",
            "player:So where would I get a staff?",
            "npc:Dramenwood staffs are crafted",
            "npc:or some such.",
            "npc:The monks are running a ship",
            "mesbox:The leprechaun magically disappears.",
        })
        t.ticks(2)
        t.expect("quest.stage.spoken_shamus", t.quest.expect_stage("spoken_shamus"))

        -- Bank the axe (the guide banks weapons before Entrana): dropped here, the zombies give one back.
        t.exec("goToEntrana-bankAxe", t.player.drop, "bronze_axe")
        t.ticks(2)
        t.exec("goto-goToEntrana", t.player.goto_tile, 3049, 3236, 0)
        t.exec("goToEntrana", t.player.talk_to, "shipmonk1_c", 1)
        t.exec("goToEntrana-dialog", t.chat.play, {
            "npc:Do you seek passage to holy En",
            "choose:Yes, okay, I'm ready to go.",
            "player:Yes, okay, I'm ready to go.",
            "npc:Very well. One moment please.",
            "mesbox:The monk quickly searches you.",
